gjp(){return"\u0e28\u0e36\u0e01\u0e1a\u0e2d\u0e2a"},
gka(){return"\u0e2d\u0e31\u0e19\u0e14\u0e31\u0e1a\u0e42\u0e25\u0e01"},
gix(){return"\u0e1c\u0e39\u0e49\u0e40\u0e25\u0e48\u0e19\u0e2b\u0e25\u0e32\u0e22\u0e04\u0e19"},
gnH(){return"\u0e1e\u0e37\u0e49\u0e19\u0e17\u0e35\u0e48\u0e42\u0e06\u0e29\u0e13\u0e32\u0e41\u0e1a\u0e19\u0e40\u0e19\u0e2d\u0e23\u0e4c"},
